import json, pathlib, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd();

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

def verify(name, source, expect_rc):
    root = write_project(name, source)
    proc = subprocess.run(['cargo', 'run', '-q', '-p', 'fz', '--', 'verify', str(root), '--json'], cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    assert proc.returncode == expect_rc, (name, proc.returncode, payload, proc.stderr)
    return payload

def messages(payload):
    return [item['message'] for item in payload['items']]

def find_message(payload, needle):
    return next(item for item in payload['items'] if needle in item['message'])

conditional_join_fail = verify('conditional_join_fail', '''
    use core.http;
    fn main() -> i32 {
        let listener = http.bind("127.0.0.1:8787");
        if true {
            close(listener);
        }
        close(listener);
        return 0;
    }
''', 1)
conditional_messages = messages(conditional_join_fail)
assert any('divergent ownership state for `listener`' in message for message in conditional_messages), conditional_join_fail
assert any('conditionally consumed value `listener`' in message for message in conditional_messages), conditional_join_fail
assert any('consumes non-owned or already-consumed value `listener` via `close`' in message for message in conditional_messages), conditional_join_fail

conditional_join_pass = verify('conditional_join_pass', '''
    use core.http;
    fn main() -> i32 {
        let listener = http.bind("127.0.0.1:8787");
        if true {
            close(listener);
        } else {
            close(listener);
        }
        return 0;
    }
''', 0)
assert conditional_join_pass['errors'] == 0, conditional_join_pass

loop_join_fail = verify('loop_join_fail', '''
    use core.http;
    fn main() -> i32 {
        let mut first = true;
        let listener = http.bind("127.0.0.1:8787");
        while first {
            close(listener);
            first = false;
            continue;
        }
        close(listener);
        return 0;
    }
''', 1)
loop_messages = messages(loop_join_fail)
assert any('divergent ownership state for `listener` across loop iterations' in message for message in loop_messages), loop_join_fail
assert any('conditionally consumed value `listener`' in message for message in loop_messages), loop_join_fail
assert any('consumes non-owned or already-consumed value `listener` via `close`' in message for message in loop_messages), loop_join_fail

loop_local_pass = verify('loop_local_pass', '''
    use core.http;
    fn main() -> i32 {
        let mut first = true;
        while first {
            let listener = http.bind("127.0.0.1:8787");
            close(listener);
            first = false;
        }
        return 0;
    }
''', 0)
assert loop_local_pass['errors'] == 0, loop_local_pass

returned_call_lifetime_fail = verify('returned_call_lifetime_fail', '''
    fn borrow(v: &'b i32) -> &'b i32 {
        return v;
    }
    fn relay(a: &'a i32, b: &'b i32) -> &'a i32 {
        return borrow(b);
    }
    fn main() -> i32 {
        return 0;
    }
''', 1)
lifetime_diag = find_message(returned_call_lifetime_fail, 'returns reference expression with mismatched lifetime')
assert 'lifetime/region-safe ownership handoff' in (lifetime_diag.get('help') or ''), lifetime_diag

returned_call_lifetime_pass = verify('returned_call_lifetime_pass', '''
    fn borrow(v: &'a i32) -> &'a i32 {
        return v;
    }
    fn relay(a: &'a i32) -> &'a i32 {
        return borrow(a);
    }
    fn main() -> i32 {
        return 0;
    }
''', 0)
assert returned_call_lifetime_pass['errors'] == 0, returned_call_lifetime_pass
assert not any('mismatched lifetime' in message for message in messages(returned_call_lifetime_pass)), returned_call_lifetime_pass

print('compiler-verify-control-flow-surface-ok')

